<?php
declare(strict_types=1);
require_once __DIR__.'/config/database.php';
$error=null;$success=null;$sessions=[];
try{
    $pdo=business_db();security_step17_ensure($pdo);$actor=security_step17_current_user($pdo);$ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];$csrf=security_step17_csrf();
    if($_SERVER['REQUEST_METHOD']==='POST'){
        security_step17_verify_csrf((string)($_POST['csrf']??''));$sid=(int)($_POST['session_id']??0);security_step17_revoke_session($pdo,$sid,trim((string)($_POST['reason']??'Administrator revoked session'))?:'Administrator revoked session');$success='Session #'.$sid.' revoked.';
    }
    $stmt=$pdo->prepare("SELECT s.*,u.full_name,u.email,(s.id=?) is_current FROM security_sessions s JOIN system_users u ON u.id=s.user_id WHERE s.organization_id=? ORDER BY (s.revoked_at IS NULL AND s.expires_at>NOW()) DESC,s.last_seen_at DESC,s.id DESC LIMIT 200");$stmt->execute([(int)($actor['session_row_id']??0),$orgId]);$sessions=$stmt->fetchAll();
}catch(Throwable $e){$error=$e->getMessage();$csrf=$csrf??'';}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Security Sessions - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="security_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 17 • Session Control</small></span></a><div class="os-top-actions"><a class="os-btn" href="security_audit.php">Audit</a><a class="os-btn primary" href="security_center.php">Security</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Security</div><nav class="os-nav"><a href="security_center.php"><i class="dot"></i>Security Center</a><a href="user_management.php"><i class="dot"></i>Users</a><a href="permission_matrix.php"><i class="dot"></i>Permissions</a><a class="active" href="security_sessions.php"><i class="dot"></i>Sessions</a><a href="security_audit.php"><i class="dot"></i>Audit</a></nav><div class="os-sidebar-status"><b>Server-side revoke</b><span>Revoked sessions fail on the next protected request even if the browser still has its cookie.</span></div></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">ACTIVE SESSION CONTROL</div><h1>See where Business OS accounts are signed in and revoke access immediately.</h1><p>Session IDs are stored only as SHA-256 hashes. IP and browser user-agent are retained for security traceability.</p></section><?php if($error):?><div class="pp-alert bad"><strong>Sessions:</strong> <?= security_step17_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Done:</strong> <?= security_step17_h($success) ?></div><?php endif;?><section class="os-card"><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>User</th><th>Role</th><th>Created</th><th>Last Seen</th><th>Expires</th><th>Client</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($sessions as $s):$active=$s['revoked_at']===null&&strtotime((string)$s['expires_at'])>time();?><tr><td><b><?= security_step17_h($s['full_name']) ?></b><small><?= security_step17_h($s['email']) ?><?= (int)$s['is_current']===1?' • CURRENT':'' ?></small></td><td><?= security_step17_h(strtoupper((string)$s['role_code'])) ?></td><td><?= security_step17_h($s['created_at']) ?></td><td><?= security_step17_h($s['last_seen_at']) ?></td><td><?= security_step17_h($s['expires_at']) ?></td><td><?= security_step17_h($s['ip_address']?:'—') ?><small><?= security_step17_h(substr((string)($s['user_agent']??''),0,80)) ?></small></td><td><span class="pp-badge <?= $active?'':'warn' ?>"><?= $active?'ACTIVE':'REVOKED / EXPIRED' ?></span><?php if($s['revoke_reason']):?><small><?= security_step17_h($s['revoke_reason']) ?></small><?php endif;?></td><td><?php if($active):?><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= security_step17_h($csrf) ?>"><input type="hidden" name="session_id" value="<?= (int)$s['id'] ?>"><input name="reason" value="Administrator revoked session" required minlength="5"><button>Revoke</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$sessions):?><tr><td colspan="8">No security sessions recorded yet.</td></tr><?php endif;?></tbody></table></div></section><div class="os-footer-note"><strong>Session limits:</strong> idle timeout and absolute timeout are enforced server-side. Password changes revoke every other active session automatically.</div></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
